  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 5, $j$2.1 Customers and Market Research$j$, $j${"readings": [{"title": "Proverbs 15 (King James Version)", "url": "/portal/bible/Proverbs/15"}], "body": "A business exists to serve customers. Proverbs 15:22 says, Without counsel purposes are disappointed: but in the multitude of counsellors they are established. Good decisions begin with listening to the people you serve.\n\nA market is the group of people who might buy what you offer. A target market is the specific group you serve best, described by age, location, needs, interests and income. A business that tries to serve everyone often serves no one well. A church bakery, for example, may target families in a particular neighborhood who want fresh bread for gatherings.\n\nMarket research is gathering information about customers and competitors. Primary research is information you collect yourself, such as surveys, interviews and observation. Secondary research uses information others have already collected, such as census data, library resources and industry reports. A simple survey asks short, clear questions such as: What do you buy now? What do you like and dislike about it? How much would you pay? Where do you look for this? Ask a variety of people, keep their answers private, and never collect sensitive personal information from strangers. Parents or teachers should approve surveys given to others.\n\nGood research reveals needs, prices customers accept and ways to stand out. Keep listening after you open. Customer feedback is a free education.\n\nYour task: (1) Define market, target market, primary research and secondary research. (2) Write five survey questions for your business idea. (3) Describe your target customer in three sentences.\n\nFlorida standards: Florida Entrepreneurship course standards (course 8812100).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida Entrepreneurship course standards (course 8812100)", "script": "Welcome back. Listen, Proverbs 15:22 says, Without counsel purposes are disappointed: but in the multitude of counsellors they are established. Good decisions begin with listening.\n\nNow watch this. A market is the group of people who might buy what you offer. A target market is the specific group you serve best, described by age, location, needs and interests. A business that tries to serve everyone often serves no one well.\n\nMarket research is gathering information. Primary research is what you collect yourself, with surveys, interviews and observation. Secondary research uses information others collected, like census data and reports.\n\nAsk short, clear questions. Keep answers private, never collect sensitive information and have a parent or teacher approve surveys.\n\nCustomer feedback is a free education.\n\nYour task is to define four terms, write five survey questions and describe your target customer. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.1 Customers and Market Research$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 6, $j$2.2 Competition and Your Value Proposition$j$, $j${"readings": [{"title": "Proverbs 27 (King James Version)", "url": "/portal/bible/Proverbs/27"}], "body": "Almost every business has competition. Competition means other businesses that offer something similar or that meet the same need in another way. Competition is not an enemy. It pushes businesses to improve, and it gives customers choices. Proverbs 27:17 says, Iron sharpeneth iron; so a man sharpeneth the countenance of his friend. Respectful competition can sharpen everyone.\n\nDirect competitors offer the same product. Indirect competitors meet the same need differently. For a tutoring service, a direct competitor is another tutor, and an indirect competitor may be a video lesson website. Study competitors honestly: What do they offer? What do they charge? What do customers say? Where do they fall short? Never lie about competitors or damage their name. Romans 12:18 says, If it be possible, as much as lieth in you, live peaceably with all men.\n\nA value proposition is a short statement of why a customer should choose you. It names the customer, the problem you solve and the benefit you provide. Example: I help middle school students raise their math grades through patient, friendly tutoring they can afford. A strong value proposition is clear, specific and true. It could rest on quality, price, convenience, speed, reliability, personal care or faith based values.\n\nA SWOT analysis lists your strengths, weaknesses, opportunities and threats. Strengths and weaknesses are inside the business. Opportunities and threats come from outside. SWOT helps you plan honestly.\n\nYour task: (1) List two direct and two indirect competitors for your idea. (2) Write your value proposition. (3) Complete a four box SWOT.\n\nFlorida standards: Florida Entrepreneurship course standards (course 8812100).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida Entrepreneurship course standards (course 8812100)", "script": "Welcome back. Listen, Proverbs 27:17 says, Iron sharpeneth iron; so a man sharpeneth the countenance of his friend. Respectful competition sharpens everyone.\n\nNow watch this. Competition means other businesses meeting the same need. Direct competitors offer the same product. Indirect competitors meet the need another way. Study them honestly, and never lie about them or damage their name. Romans 12:18 says to live peaceably with all men as much as lieth in you.\n\nA value proposition is a short statement of why a customer should choose you. It names the customer, the problem and the benefit.\n\nA SWOT analysis lists strengths, weaknesses, opportunities and threats. Strengths and weaknesses are inside. Opportunities and threats are outside.\n\nYour task is to list competitors, write a value proposition and complete a SWOT. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.2 Competition and Your Value Proposition$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 7, $j$2.3 Pricing Wisely and Fairly$j$, $j${"readings": [{"title": "Proverbs 20 (King James Version)", "url": "/portal/bible/Proverbs/20"}], "body": "Pricing is one of the most important decisions in a business. Proverbs 20:10 says, Divers weights, and divers measures, both of them are alike abomination to the LORD. A fair price is honest, clearly stated and the same for similar customers.\n\nStart with costs. Fixed costs stay the same no matter how much you sell, such as rent or a monthly website fee. Variable costs change with each item, such as ingredients or packaging. The total cost per item equals variable cost plus a share of fixed costs. If a cake costs 6 dollars in ingredients and packaging, the price must be higher than 6 dollars for you to earn anything.\n\nA simple method is cost plus pricing: add a markup to cost. If cost is 6 dollars and you want a 50 percent markup, the markup is 3 dollars and the price is 9 dollars. Profit margin compares profit to price. A 3 dollar profit on a 9 dollar price is a margin of about 33 percent. Also consider what customers will pay and what competitors charge. Pricing too low can hide a loss and signal low quality. Pricing too high can drive customers away.\n\nBe honest about discounts, fees and total cost. Do not use bait and switch tricks or hidden charges. Do not charge more because a customer seems unaware. Keep a written price list and quote the same price to the same kind of customer. Ecclesiastes 5:10 reminds us that he that loveth silver shall not be satisfied with silver.\n\nYour task: (1) Define fixed cost and variable cost. (2) Compute the price for an item costing 8 dollars with a 50 percent markup. (3) Explain why honest pricing matters.\n\nFlorida standards: Florida Entrepreneurship course standards (course 8812100).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida Entrepreneurship course standards (course 8812100)", "script": "Welcome back. Listen, Proverbs 20:10 says, Divers weights, and divers measures, both of them are alike abomination to the LORD. A fair price is honest and clearly stated.\n\nNow watch this. Fixed costs stay the same no matter how much you sell, like rent. Variable costs change with each item, like ingredients. Your price must be higher than your cost to earn anything.\n\nCost plus pricing adds a markup. If an item costs 6 dollars and you add 50 percent, the markup is 3 dollars and the price is 9 dollars. Profit margin compares profit to price. Three dollars on a nine dollar price is about 33 percent.\n\nAlso consider what customers will pay and what competitors charge. Be honest about fees and discounts. Do not use hidden charges.\n\nYour task is to define two costs, compute a price and explain honest pricing. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.3 Pricing Wisely and Fairly$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 8, $j$2.4 Marketing, Branding and a Good Name$j$, $j${"readings": [{"title": "Proverbs 22 (King James Version)", "url": "/portal/bible/Proverbs/22"}], "body": "Marketing is everything you do to let customers know about your business and to build relationships with them. Proverbs 22:1 says, A good name is rather to be chosen than great riches, and loving favour rather than silver and gold. Your name is your brand, and your brand is your promise.\n\nBranding includes your business name, logo, colors, voice and the experience customers have. Choose a name that is clear, easy to say and not already used by someone else. Be consistent. A good brand tells people who you are and what to expect.\n\nThe four Ps of marketing are product, price, place and promotion. Product is what you offer. Price is what you charge. Place is where and how customers buy. Promotion is how you tell people. Promotion can include word of mouth, flyers approved by the place where they are posted, a church bulletin with permission, a simple website with adult help, social media with proper privacy and age rules, business cards, and referrals from happy customers.\n\nHonest advertising is required. Do not exaggerate, make false claims, use someone else's photos or music without permission, or post private information about customers. Respect rules about children and online accounts: many social platforms require users to be thirteen or older, and any student account used for business should be managed with a parent or guardian.\n\nTest your marketing, track what works and thank customers. Proverbs 25:11 says, A word fitly spoken is like apples of gold in pictures of silver.\n\nYour task: (1) Define marketing and brand. (2) List the four Ps for your idea. (3) Write a three sentence honest advertisement.\n\nFlorida standards: Florida Entrepreneurship course standards (course 8812100).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida Entrepreneurship course standards (course 8812100)", "script": "Welcome back. Listen, Proverbs 22:1 says, A good name is rather to be chosen than great riches. Your name is your brand, and your brand is your promise.\n\nNow watch this. Marketing is everything you do to let customers know about your business and build relationships. Branding includes your name, logo, colors and the experience people have.\n\nThe four Ps are product, price, place and promotion. Promotion can be word of mouth, flyers with permission, a church bulletin, a simple website with adult help and referrals.\n\nAdvertising must be honest. Do not exaggerate, make false claims, use someone else's photos or music without permission or share private customer information. Many platforms require users to be thirteen or older, so any student business account should be managed with a parent or guardian.\n\nTrack what works and thank customers.\n\nYour task is to define two terms, list the four Ps and write an honest advertisement. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.4 Marketing, Branding and a Good Name$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 2, $j$Assessment 2: Customers, Competition, Pricing and Marketing$j$, $j${"prompt": "Write a report of at least 250 words. Use complete sentences and label each part. Proverbs 22:1 says, A good name is rather to be chosen than great riches, and loving favour rather than silver and gold.\n\nPart 1: Define market, target market, primary research and secondary research. Describe your target customer and five survey questions.\nPart 2: Name direct and indirect competitors for your idea, write a value proposition and complete a SWOT analysis.\nPart 3: Define fixed and variable costs. Price an item with a cost of 12 dollars and a 50 percent markup and compute the profit margin. Show your work.\nPart 4: Describe the four Ps for your business and write an honest advertisement. Explain two rules for advertising online as a young person.\nPart 5: Explain how Proverbs 20:10 and Proverbs 22:1 guide pricing and branding.", "rubric": "100 points. Part 1: 20 points. Part 2: 20 points. Part 3: 25 points. Part 4: 20 points. Part 5: 10 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 2: Customers, Competition, Pricing and Marketing$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 2, $j$Discussion 2: A Good Name Is Rather to Be Chosen$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes a business you trust and why you trust it, (2) explains what the owner does that builds a good name, (3) explains one pricing or advertising practice that would damage trust, and (4) connects your answer to Proverbs 22:1, Proverbs 20:10 or Proverbs 15:22. Then write a respectful reply of at least 40 words to another student's post, or answer this question: Is it right for a Christian business to charge more than competitors? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 2: A Good Name Is Rather to Be Chosen$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 6, $j$Check 2.1: Customers and Market Research$j$, $j${"questions": [{"q": "A target market is:", "options": ["The specific group you serve best", "Only your family", "A kind of tax", "Everyone in the world"]}, {"q": "A survey you create yourself is:", "options": ["Secondary research", "Primary research", "A loan", "A tax form"]}, {"q": "Census data is an example of:", "options": ["Profit", "Secondary research", "Advertising", "Primary research"]}, {"q": "When surveying others, you should:", "options": ["Keep answers private and get adult approval", "Skip questions", "Publish names", "Collect sensitive data"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.1: Customers and Market Research$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,1,0}'::int[], array[$j$Targeting helps you serve well.$j$,$j$Primary research is collected firsthand.$j$,$j$Secondary research uses existing information.$j$,$j$Protect privacy and involve adults.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.1: Customers and Market Research$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 7, $j$Check 2.2: Competition and Your Value Proposition$j$, $j${"questions": [{"q": "A direct competitor offers:", "options": ["A different need", "A tax", "The same product", "No product"]}, {"q": "A value proposition explains:", "options": ["Your home address", "How to avoid taxes", "Why a customer should choose you", "Your salary"]}, {"q": "In SWOT, the O stands for:", "options": ["Owners", "Orders", "Offices", "Opportunities"]}, {"q": "Toward competitors a Christian owner should be:", "options": ["Secretive", "Insulting", "Deceptive", "Honest and peaceable"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.2: Competition and Your Value Proposition$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,2,3,3}'::int[], array[$j$Direct competitors sell the same thing.$j$,$j$It states the benefit you provide.$j$,$j$SWOT: strengths, weaknesses, opportunities, threats.$j$,$j$Romans 12:18 calls for peace.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.2: Competition and Your Value Proposition$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 8, $j$Check 2.3: Pricing Wisely and Fairly$j$, $j${"questions": [{"q": "Rent that stays the same each month is a:", "options": ["Fixed cost", "Markup", "Variable cost", "Profit"]}, {"q": "An item costs 10 dollars and you add a 50 percent markup. The price is:", "options": ["20 dollars", "5 dollars", "15 dollars", "12 dollars"]}, {"q": "Ingredients for each cake are a:", "options": ["Tax", "Variable cost", "Fixed cost", "Gift"]}, {"q": "Honest pricing means:", "options": ["Secret charges", "Charging unaware customers more", "Bait and switch", "Clear prices with no hidden fees"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.3: Pricing Wisely and Fairly$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,2,1,3}'::int[], array[$j$Fixed costs do not change with sales.$j$,$j$50 percent of 10 is 5, so the price is 15.$j$,$j$Variable costs change with each item.$j$,$j$Proverbs 20:10 condemns dishonest measures.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.3: Pricing Wisely and Fairly$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 9, $j$Check 2.4: Marketing, Branding and a Good Name$j$, $j${"questions": [{"q": "The four Ps are product, price, place and:", "options": ["Payroll", "Promotion", "Penalty", "Profit"]}, {"q": "Honest advertising means:", "options": ["Exaggerating", "No false claims", "Sharing customer secrets", "Using others' photos without permission"]}, {"q": "A brand is:", "options": ["A tax record", "A kind of loan", "Your promise and identity to customers", "Only a logo"]}, {"q": "Many social media platforms require users to be at least:", "options": ["Ten", "Five", "Sixty", "Thirteen"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.4: Marketing, Branding and a Good Name$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,1,2,3}'::int[], array[$j$Promotion tells people about your offer.$j$,$j$Truth in advertising builds trust.$j$,$j$Brand includes name, voice and experience.$j$,$j$Age rules apply to online accounts.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.4: Marketing, Branding and a Good Name$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 10, $j$Unit Quiz 2: Customers, Competition, Pricing and Marketing$j$, $j${"questions": [{"q": "Market research gathers information about:", "options": ["Customers and competitors", "Only logos", "Only taxes", "Only employees"]}, {"q": "A target market is described by:", "options": ["Only price", "Only names", "Age, location, needs and interests", "Only color"]}, {"q": "An indirect competitor:", "options": ["Meets the same need in another way", "Is illegal", "Sells the identical item", "Is always a friend"]}, {"q": "The O and T in SWOT are:", "options": ["Prices", "Profits", "Outside factors", "Inside factors"]}, {"q": "A fixed cost is:", "options": ["Packaging per item", "A coupon", "Ingredients per cake", "Rent each month"]}, {"q": "An item costs 20 dollars with a 25 percent markup. The price is:", "options": ["45 dollars", "30 dollars", "22 dollars", "25 dollars"]}, {"q": "Promotion is:", "options": ["What you make", "How you tell people about your offer", "Where you sell", "How much you charge"]}, {"q": "Proverbs 22:1 says a good name is:", "options": ["Rather to be chosen than great riches", "Worth nothing", "A secret", "Only for the wealthy"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 2: Customers, Competition, Pricing and Marketing$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,2,0,2,3,3,1,0}'::int[], array[$j$Research reveals needs and competition.$j$,$j$Targeting uses customer traits.$j$,$j$Indirect competitors substitute.$j$,$j$Opportunities and threats come from outside.$j$,$j$Fixed costs stay the same.$j$,$j$25 percent of 20 is 5.$j$,$j$Promotion is one of the four Ps.$j$,$j$Reputation is a treasure.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 2: Customers, Competition, Pricing and Marketing$j$ on conflict (item_id) do nothing;
